"  await check('Isolation', 'Catalog dynamic pagination generates cards with 220x330 selectors matching CSS scope', () => {
    const dom = createTestDom('movies');
    const { window } = dom;
    const ctrl = window.MoviesViewController || new window.CatalogViewController('view-movies', 'movie');
    ctrl.init();

    // Mock 12 discover items
    const mockItems = [];
    for (let i = 0; i < 12; i++) {
      mockItems.push({
        id: 2000 + i,
        title: `Movie ${i + 1}`,
        year: '2023',
        vote_average: 7.5,
        poster_path: `/poster${i}.jpg`
      });
    }

    ctrl.renderGrid(mockItems, true);

    const cards = ctrl.gridContainer.querySelectorAll('.card, .card-poster');
    assert.strictEqual(cards.length, 12, '12 cards must be rendered in catalog grid');

    for (let i = 0; i < cards.length; i++) {
      const c = cards[i];
      assert.ok(c.classList.contains('card-poster'), 'Card must have .card-poster');
      assert.ok(c.classList.contains('f'), 'Card must have .f');
      const pic = c.querySelector('.pic.poster-media');
      assert.ok(pic, 'Card must have .pic.poster-media');
    }
  });"

